// 设置今天和明天的日期范围
const today = new Date();
today.setHours(0, 0, 0, 0);
const tomorrow = new Date(today);
tomorrow.setDate(tomorrow.getDate() + 1);

return {
  todayStart: today.toISOString(),
  tomorrowStart: tomorrow.toISOString(),
  todayFormatted: today.toLocaleDateString('zh-CN')
};

/**
 * 将文章分批处理，每批10篇文章
 * 通过不同的输出端口发送不同的批次
 */
function splitArticlesIntoBatches() {
  const articles = $input.all();
  const batchSize = 10;
  const outputs = [];

  // 创建5个输出端口的数据
  for (let i = 0; i < 5; i++) {
    const startIndex = i * batchSize;
    const endIndex = Math.min(startIndex + batchSize, articles.length);

    if (startIndex < articles.length) {
      const batch = articles.slice(startIndex, endIndex);
      outputs[i] = [{
        json: {
          batchId: i + 1,
          articles: batch.map(item => item.json),
          totalBatches: Math.ceil(articles.length / batchSize),
          batchSize: batch.length
        }
      }];
    } else {
      outputs[i] = [];
    }
  }

  return outputs;
}

return splitArticlesIntoBatches();

/**
 * 聚合所有批次的评估结果并选出得分最高的5篇文章
 * 确保最终选择的文章质量最高
 */
function aggregateAndRankArticles() {
  const allBatchResults = $input.all();
  const allEvaluatedArticles = [];

  // 收集所有批次的评估结果
  allBatchResults.forEach(batchResult => {
    let jsonText = batchResult.json.text.trim();
    // 移除代码围栏
    if (jsonText.startsWith('```')) {
      jsonText = jsonText.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
    }

    try {
      const batchData = JSON.parse(jsonText);
      if (batchData.evaluated_articles && Array.isArray(batchData.evaluated_articles)) {
        allEvaluatedArticles.push(...batchData.evaluated_articles);
      }
    } catch (error) {
      console.error('解析批次结果失败:', error);
    }
  });

  // 按评分降序排序
  allEvaluatedArticles.sort((a, b) => b.score - a.score);

  // 选择得分最高的5篇文章
  const top5Articles = allEvaluatedArticles.slice(0, 5);

  // 获取原始文章数据
  const originalArticles = $('Get Today\'s AI Articles').all();

  // 为所有文章准备更新数据
  const articleUpdates = originalArticles.map(article => {
    const evaluated = allEvaluatedArticles.find(e => e.id === article.json.id);
    const isSelected = top5Articles.some(t => t.id === article.json.id);

    return {
      id: article.json.id,
      ai_score: evaluated ? evaluated.score : 0,
      selection_reason: evaluated ? evaluated.reason : '未被评估',
      evaluated_at: new Date().toISOString(),
      is_selected: isSelected
    };
  });

  // 获取选中文章的完整信息
  const selectedArticlesWithDetails = top5Articles.map(selected => {
    const fullArticle = originalArticles.find(article => 
      article.json.id === selected.id
    );

    return {
      ...fullArticle.json,
      evaluation_score: selected.score,
      selection_reason: selected.reason
    };
  });

  return {
    selectedArticles: selectedArticlesWithDetails,
    articleUpdates: articleUpdates,
    evaluationSummary: {
      total_articles: originalArticles.length,
      evaluated_articles: allEvaluatedArticles.length,
      selected_articles: top5Articles.length,
      average_score: allEvaluatedArticles.reduce((sum, a) => sum + a.score, 0) / allEvaluatedArticles.length
    }
  };
}

return aggregateAndRankArticles();

/**
 * 处理选中的文章数据，准备用于后续的摘要生成
 */
function processSelectedArticles() {
  const aggregatedData = $json;

  return {
    detailedArticles: aggregatedData.selectedArticles,
    dailySummary: {
      selected_article_ids: aggregatedData.selectedArticles.map(a => a.id),
      evaluation_summary: aggregatedData.evaluationSummary
    },
    articleUpdates: aggregatedData.articleUpdates
  };
}

return processSelectedArticles();
